import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const localesDir = path.resolve(__dirname, '../locales/zh-CN')
const outputPath = path.resolve(__dirname, '../src/typings/i18n.d.ts')
/** 每个命名空间一个 d.ts，避免单文件过大拖慢 IDE 与 tsc */
const namespaceDir = path.resolve(__dirname, '../src/typings/i18n')

const GENERATED_HEADER = `/**
 * This file is auto-generated by scripts/generate-i18n-types.mjs
 * DO NOT EDIT MANUALLY
 */`

const KEY_PATHS_NOTE = `/**
 * 语言包中可翻译叶子 key 的扁平点分联合（首段为语言包文件名命名空间）。
 *
 * 为什么生成而不是在类型层推导：用递归条件类型在 5000+ key 上做路径展开，
 * 每次 vue-tsc 都要重算，是实打实的类型检查性能风险；这里在生成期一次性算清。
 *
 * 数组值按终止路径处理（不下钻元素）：数组是 UI 列表，经 tm() 消费，
 * 不会被某个点分 t() key 直接寻址。
 */`

/**
 * 深度优先收集点分 key 路径。
 * - 字符串值 -> 叶子路径
 * - 数组值 -> 终止路径（不下钻，避免生成 `x.y.0.title` 这类非 t() key）
 * - 对象值 -> 继续下钻
 * @param {unknown} value 当前节点
 * @param {string} prefix 当前前缀（不含尾部点）
 * @param {string[]} out 收集结果
 */
function collectKeyPaths(value, prefix, out) {
  if (typeof value !== 'object' || value === null) {
    out.push(prefix)
    return
  }
  if (Array.isArray(value)) {
    out.push(prefix)
    return
  }
  for (const [key, child] of Object.entries(value)) {
    collectKeyPaths(child, prefix ? `${prefix}.${key}` : key, out)
  }
}

/**
 * 渲染单个命名空间的类型文件。
 * @param {string} namespace 语言包文件名（去扩展名）
 * @param {unknown} content 语言包内容
 */
function buildNamespaceContent(namespace, content) {
  const keyPaths = []
  collectKeyPaths(content, namespace, keyPaths)

  const union = keyPaths.length > 0 ? `\n${keyPaths.map((key) => `  | ${JSON.stringify(key)}`).join('\n')}` : ' never'
  return {
    keyPathCount: keyPaths.length,
    content: `${GENERATED_HEADER}

export type Messages = ${JSON.stringify(content, null, 2)}

${KEY_PATHS_NOTE}
export type KeyPaths =${union}
`
  }
}

/**
 * 渲染聚合文件 `src/typings/i18n.d.ts`：只做 import + 类型组合，
 * 具体字面量分散在 `src/typings/i18n/<namespace>.d.ts`。
 * @param {string[]} namespaces 命名空间列表（顺序需与 readdirSync 一致）
 */
function buildAggregateContent(namespaces) {
  const imports = namespaces.map(
    (namespace) =>
      `import type { Messages as ${namespace}Messages, KeyPaths as ${namespace}KeyPaths } from './i18n/${namespace}'`
  )
  const keyEntries = namespaces.map((namespace) => `  ${JSON.stringify(namespace)}: ${namespace}Messages`)
  const unionEntries = namespaces.map((namespace) => `  | ${namespace}KeyPaths`)

  return `${GENERATED_HEADER}

${imports.join('\n')}

export type I18nKeys = {
${keyEntries.join('\n')}
}

${KEY_PATHS_NOTE}
export type I18nKeyPaths =
${unionEntries.join('\n')}
`
}

function generateTypes() {
  const files = fs.readdirSync(localesDir).filter((file) => file.endsWith('.json'))
  /** @type {Array<{ namespace: string, content: unknown }>} */
  const packs = []

  for (const file of files) {
    const namespace = path.basename(file, '.json')
    const content = JSON.parse(fs.readFileSync(path.join(localesDir, file), 'utf-8'))
    packs.push({ namespace, content })
  }

  // 整体重建目录：语言包被删除/重命名时不留陈旧 d.ts
  fs.rmSync(namespaceDir, { recursive: true, force: true })
  fs.mkdirSync(namespaceDir, { recursive: true })

  let keyPathCount = 0
  let maxNamespaceLines = 0
  for (const { namespace, content } of packs) {
    const built = buildNamespaceContent(namespace, content)
    keyPathCount += built.keyPathCount
    maxNamespaceLines = Math.max(maxNamespaceLines, built.content.split('\n').length)
    fs.writeFileSync(path.join(namespaceDir, `${namespace}.d.ts`), built.content)
  }

  const aggregate = buildAggregateContent(packs.map((pack) => pack.namespace))
  fs.writeFileSync(outputPath, aggregate)

  console.log(
    `[i18n] Generated ${packs.length} namespace files to ${namespaceDir} ` +
      `(max ${maxNamespaceLines} lines/file) and aggregate to ${outputPath} ` +
      `(${aggregate.split('\n').length} lines, ${keyPathCount} key paths)`
  )
}

generateTypes()
